// create-weft: write a new app's files (research 26 §6, research 28 §6). `--ui`: `warp` adds @weft/warp and `warp()` in
// weft.config.ts, `headless` adds @weft/ui-core's spec CSS under the app's own markup, `tailwind` adds Tailwind and its Vite plugin,
// `none` adds nothing. `--db`, `--layer`
// and `--auth` add a database, a todo app and a sign-in flow (stack.mjs); `--runtime` is what `weft build` targets.
// Everything else (AGENTS.md, .weft/, the slot modules) is generated by `weft` itself on the first `weft dev` or
// `weft check`, so a scaffold never goes stale against the CLI.

import { randomBytes } from 'node:crypto'
import { existsSync, mkdirSync, readdirSync, writeFileSync } from 'node:fs'
import { basename, dirname, join } from 'node:path'
import { customAuth } from './data.mjs'
import { classes, context, loginPage, stackDeps, stackFiles, TAILWIND_CSS, TAILWIND_VITE, tailwindPackages, todosPage } from './stack.mjs'

export const UI = ['warp', 'headless', 'tailwind', 'none']
export const DB = ['sqlite', 'postgres', 'mysql', 'none']
export const LAYERS = ['drizzle', 'prisma', 'native']
export const RUNTIMES = ['node', 'bun', 'deno']
export const CONFIGS = ['ts', 'json', 'yaml']


const json = v => JSON.stringify(v, null, 2) + '\n'
const title = name => name.replace(/[-_]+/g, ' ').replace(/\b\w/g, c => c.toUpperCase())

/** `weft.config.ts`, `.json` or `.yaml`: one schema, so the same app in each (research 34 §2). */
const LAYER_PLUGIN = { prisma: { pkg: '@weft/plugin-db-prisma', name: 'prisma' }, native: { pkg: '@weft/plugin-db-native', name: 'native' } }

const appPlugins = ({ ui, layer }) => [...(ui === 'warp' ? [{ pkg: '@weft/warp', name: 'warp' }] : []), ...(LAYER_PLUGIN[layer] ? [LAYER_PLUGIN[layer]] : [])]

/** What each plugin a scaffold picks declares. `weft check` fails a scaffold where these fall behind the plugin. */
const GRANTS = {
  '@weft/warp': ['fs.read:node_modules/@weft/ui-core/**', 'fs.write:$TMPDIR/warp-seed-*', 'spawn:node'],
  '@weft/plugin-db-prisma': ['fs.read:prisma/**', 'fs.write:prisma/migrations/**', 'spawn:node'],
  '@weft/plugin-db-native': ['fs.read:migrations/**', 'fs.write:migrations/**'],
}

/** Choosing a plugin here is approving it. There's no install yet, so `weft plugins approve --all` pins the code later. */
function pluginLock(options) {
  const plugins = Object.fromEntries(appPlugins(options).map(p => [p.pkg, { version: null, integrity: null, permissions: GRANTS[p.pkg], provides: [], undeclared: [] }]))
  return Object.keys(plugins).length ? { '.weft/plugins.lock.json': json({ version: 1, plugins }) } : {}
}

function configFile(format, { ui, label, runtime, layer }) {
  const plugins = appPlugins({ ui, layer })
  const site = { name: label, title: `%s · ${label}`, description: 'Made with weft.' }
  if (format === 'json') {
    const config = { $schema: './.weft/config.schema.json', site, ...(plugins.length && { plugins: plugins.map(p => p.pkg) }), ...(runtime !== 'node' && { runtime }) }
    return { 'weft.config.json': json(config) }
  }
  if (format === 'yaml') {
    return {
      'weft.config.yaml':
        `# yaml-language-server: $schema=./.weft/config.schema.json\nsite:\n` +
        Object.entries(site).map(([k, v]) => `  ${k}: ${JSON.stringify(v)}\n`).join('') +
        (plugins.length ? `plugins:\n${plugins.map(p => `  - "${p.pkg}"\n`).join('')}` : '') +
        (runtime !== 'node' ? `runtime: ${runtime}\n` : ''),
    }
  }
  return {
    'weft.config.ts':
      `import { defineConfig } from 'weft/config'\n` +
      plugins.map(p => `import { ${p.name} } from '${p.pkg}/plugin'\n`).join('') +
      `\nexport default defineConfig({\n` +
      `  site: { name: ${JSON.stringify(label)}, title: ${JSON.stringify(site.title)}, description: 'Made with weft.' },\n` +
      (plugins.length ? `  plugins: [${plugins.map(p => `${p.name}()`).join(', ')}],\n` : '') +
      (runtime !== 'node' ? `  runtime: '${runtime}',\n` : '') +
      `})\n`,
  }
}

/** The files for an app, as `{ path: text }`. */
export function template({ ui = 'warp', name = 'weft-app', version = '0.0.0', db = 'none', layer = 'drizzle', auth = false, runtime = 'node', config = 'ts', secret = randomBytes(32).toString('base64') } = {}) {
  if (!UI.includes(ui)) throw new Error(`--ui must be one of ${UI.join(', ')} (got "${ui}")`)
  if (!DB.includes(db)) throw new Error(`--db must be one of ${DB.join(', ')} (got "${db}")`)
  if (!RUNTIMES.includes(runtime)) throw new Error(`--runtime must be one of ${RUNTIMES.join(', ')} (got "${runtime}")`)
  if (!CONFIGS.includes(config)) throw new Error(`--config must be one of ${CONFIGS.join(', ')} (got "${config}")`)
  if (!LAYERS.includes(layer)) throw new Error(`--layer must be one of ${LAYERS.join(', ')} (got "${layer}")`)
  if (auth && db === 'none') throw new Error('--auth keeps users in a database: add --db sqlite, postgres or mysql')
  const label = title(name)
  const stack = stackDeps({ db, auth: auth === true, layer, version })
  const deps = { weft: version, '@weft/start': version }
  if (ui === 'warp') deps['@weft/warp'] = version
  if (ui === 'headless') deps['@weft/ui-core'] = version
  if (ui === 'tailwind') Object.assign(stack.dev, tailwindPackages)

  const files = {
    'package.json': json({
      name,
      private: true,
      type: 'module',
      scripts: { dev: 'weft dev', build: 'weft build', check: 'weft check', start: 'weft start', ...(db !== 'none' && { 'db:generate': 'weft db generate' }), ...(db !== 'none' && layer === 'prisma' && { postinstall: 'prisma generate' }) },
      dependencies: { ...deps, ...stack.deps },
      devDependencies: { '@weft/cli': version, typescript: '7.0.2', ...stack.dev },
    }),
    ...configFile(config, { ui, label, runtime, layer: db === 'none' ? 'drizzle' : layer }),
    'tsconfig.json': json({
      compilerOptions: {
        target: 'es2022', module: 'esnext', moduleResolution: 'bundler', strict: true, noEmit: true, skipLibCheck: true,
        jsx: 'preserve', jsxImportSource: 'weft', lib: ['es2023', 'dom', 'dom.iterable'], paths: { '#/*': ['./src/*'] }, types: db === 'none' ? ['weft/client'] : ['weft/client', 'node'],
      },
      include: ['src', ...(config === 'ts' ? ['weft.config.ts'] : []), '.weft/*.d.ts'],
    }),
    '.gitignore': `node_modules/\n.weft/*\n!.weft/plugins.lock.json\n.output/\ndist/\n${db === 'none' ? '' : '.env\n.data/\n'}${layer === 'prisma' ? 'src/generated/\n' : ''}`,
    'src/routes/_layout.tsx': layout(ui, { db, auth }),
    'src/routes/index.tsx': home(ui, label),
    'src/routes/about.tsx': `export const meta = { title: 'About', description: 'What this app is.' }\n\nexport default function About() {\n  return <h1>About</h1>\n}\n`,
  }
  Object.assign(files, pluginLock({ ui, layer }))
  if (ui !== 'warp') files['src/app.css'] = css(ui)
  if (ui === 'tailwind') files['vite.config.ts'] = TAILWIND_VITE
  if (db !== 'none') {
    Object.assign(files, stackFiles({ db, auth: auth === true, name, secret, layer }), { 'src/routes/todos/index.tsx': todosPage(ui, auth === true) })
    if (auth === true) files['src/routes/login.tsx'] = loginPage(ui)
    if (auth === 'custom') Object.assign(files, { 'src/auth.server.ts': customAuth, 'src/context.server.ts': context(true) })
  }
  return files
}

/** Write the app into `dir` (which must be missing or empty). */
export function scaffold(dir, options = {}) {
  if (existsSync(dir) && readdirSync(dir).length) throw new Error(`${dir} is not empty`)
  const files = template({ name: basename(dir).toLowerCase().replace(/[^a-z0-9-_.]/g, '-'), ...options })
  for (const [rel, text] of Object.entries(files)) {
    mkdirSync(dirname(join(dir, rel)), { recursive: true })
    writeFileSync(join(dir, rel), text)
  }
  return { dir, files: Object.keys(files) }
}

function layout(ui, options) {
  const text = shell(ui, options)
  return ui === 'tailwind' ? text.replace('<nav>', '<nav class="flex gap-4 p-4">').replace('<main>', '<main class="p-4">') : text
}

function shell(ui, { db, auth: which }) {
  const auth = which === true
  const imports = ui === 'warp' ? '' : (ui === 'headless' ? `import '@weft/ui-core/styles/warp.css'\n` : '') + `import '../app.css'\n`
  const links = db === 'none' ? '' : `\n        <Link href="/todos">Todos</Link>`
  if (!auth) {
    return `${imports}import { Link, type RouteProps } from '@weft/start'

export default function Root(props: RouteProps) {
  return (
    <>
      <nav>
        <Link href="/">Home</Link>
        <Link href="/about">About</Link>${links}
      </nav>
      <main>{props.children}</main>
    </>
  )
}
`
  }
  return `${imports}import { Link, type LoadArgs, type RouteProps } from '@weft/start'
import { me, signOut } from '#/server/session'

export const load = ({ ctx }: LoadArgs) => me.fetch()

export default function Root(props: RouteProps<typeof load>) {
  return (
    <>
      <nav>
        <Link href="/">Home</Link>
        <Link href="/about">About</Link>${links}
        {props.data ? <button type="button" onClick={() => signOut()}>Sign out</button> : <Link href="/login">Sign in</Link>}
      </nav>
      <main>{props.children}</main>
    </>
  )
}
`
}

function home(ui, label) {
  if (ui === 'warp') {
    return `import type { Meta } from '@weft/start'
import { state } from 'weft'
import { Badge, Button, Card } from '@weft/warp'

export const meta: Meta = { title: { absolute: ${JSON.stringify(label)} }, description: ${JSON.stringify(`${label}, made with weft.`)} }

export default function Home() {
  const count = state(0)
  return (
    <Card eyebrow="weft + warp" title=${JSON.stringify(`Welcome to ${label}`)}>
      <p>
        Clicked <Badge>{count.value}</Badge> times.
      </p>
      <Button onClick={() => count.value++}>Click</Button>
    </Card>
  )
}
`
  }
  return `import type { Meta } from '@weft/start'
import { state } from 'weft'

export const meta: Meta = { title: { absolute: ${JSON.stringify(label)} }, description: ${JSON.stringify(`${label}, made with weft.`)} }

export default function Home() {
  const count = state(0)
  return (
    <section class=${JSON.stringify(classes(ui, 'card'))}>
      <h1${named(ui, 'title')}>Welcome to ${label}</h1>
      <button${named(ui, 'button')} type="button" onClick={() => count.value++}>
        Clicked {count.value} times
      </button>
    </section>
  )
}
`
}

const named = (ui, part) => (classes(ui, part) ? ` class="${classes(ui, part)}"` : '')

function css(ui) {
  if (ui === 'tailwind') return TAILWIND_CSS
  // headless rides warp's tokens (ui-core's warp.css, the fluid title size included); none brings its own.
  const v = ui === 'headless'
    ? { bg: 'var(--warp-color-page)', fg: 'var(--warp-color-text)', accent: 'var(--warp-color-accent-solid)', radius: 'var(--warp-radius-surface)', title: 'var(--warp-text-title-size)' }
    : { bg: 'Canvas', fg: 'CanvasText', accent: 'LinkText', radius: '8px', title: 'clamp(1.5rem, 1.2rem + 2cqi, 2.5rem)' }
  return `:root { color-scheme: light dark; }
body { margin: 0; font-family: system-ui, sans-serif; background: ${v.bg}; color: ${v.fg}; }
nav { display: flex; gap: 1rem; padding: 1rem; }
main { padding: 1rem; max-inline-size: 60rem; margin-inline: auto; }
.card { container-type: inline-size; padding: 1.5rem; border-radius: ${v.radius}; border: 1px solid color-mix(in oklab, currentColor 15%, transparent); }
.card h1 { font-size: ${v.title}; }
button { font: inherit; padding: 0.5rem 1rem; border-radius: ${v.radius}; border: 1px solid ${v.accent}; background: none; color: inherit; }
`
}
